// append runs out of memory.
/**
 * @brief Parses the parts of an interpolated string (INTERP_PARTS) up to its
 * closing token and attaches them to the INTERP_STRING node.
 *
 * Called with the opening token already consumed. INTERP_STRING ->
 * S_STRING_START INTERP_PARTS S_STRING_END | TRIPLE_S_STRING_START INTERP_PARTS
 * TRIPLE_S_STRING_END, INTERP_PART -> STRING | IDENT | DOLLAR_EXPRESSION_START
 * INLINE_VALUE DOLLAR_EXPRESSION_END. The string's node is owned by the
 * precedence stack, and every part is attached right after it is created
 * (like attach_node in parser.c), before any token is consumed, so a syntax
 * error leaves each subtree owned exactly once (ADR-0004). The closing `}` is
 * not a precedence terminal: the expression inside `${…}` ends at it (it is no
 * operand or operator) and it is consumed here.
 */
static void build_interp_string(Ctx* ctx,
                                Parser* parser,
                                AstNode* string,
                                TokenType close) {
  while (parser->current.type != close) {
    const Token* token = &parser->current;
    if (token->type == DOLLAR_EXPRESSION_START) {
      parser_advance(ctx, parser);
      parse_inline_value(ctx, parser, string);
      parser_expect(ctx, parser, DOLLAR_EXPRESSION_END);
      continue;
    }
    if (token->type != STRING && token->type != IDENT)
      parser_syntax_error(ctx, parser, "text, name, ${ or end of string");

    AstNode* part;
    ast_node_create(ctx, &part);
    parser_attach(ctx, parser, string, part);
    ast_node_set_position(part, token->line, token->column);
    if (token->type == STRING) {
      ast_node_set_type(part, AST_NODE_STRING_LIT);
      ast_node_set_value(ctx, part,
                         (AstNodeValue){.string_value = token->value.text});
    } else {
      ast_node_set_type(part, AST_NODE_IDENT);
      ast_node_set_name(ctx, part, token->value.text);
    }
    parser_advance(ctx, parser);
  }
  parser_advance(ctx, parser);  // the closing token
}

