/**
 * @brief Returns whether the current token is a `(` directly followed by `if`,
 * the start of an if expression operand
 */
static bool starts_inline_if(Ctx* ctx, Parser* parser) {
  return parser->current.type == L_PAREN &&
         parser_peek(ctx, parser)->type == IF;
}

// AI generated by: Claude Code / Claude Sonnet 5.5
// Prompt: "implementation done using skill: mattpocock-skills:implement-spec,
// ticket 05: if statements and if expressions"
// Changes: added shift_inline_if, an if expression in parentheses is one
// operand whose IF is built by the IF_INLINE callback.
/**
 * @brief Shifts `( if ... )` as one `i`, the operand being the IF
 *
 * The callback attaches its IF to a NONE holder node (the operand entry owns
 * it from the start, so a THROW inside leaves the partly built IF owned by the
 * stack, ADR-0004). Afterwards the IF is detached from the holder, which is
 * destroyed, and becomes the operand's node. Only indices are used: the stack
 * may move while the nested expressions are parsed.
 */
static void shift_inline_if(Ctx* ctx, Parser* parser) {
  PrecStack* stack = &parser->prec_stack;
  size_t index = stack_push(ctx, stack, PREC_ENTRY_TERMINAL, PREC_OPERAND);

  AstNode* holder;
  ast_node_create(ctx, &holder);
  stack->data[index].node = holder;
  ast_node_set_type(holder, AST_NODE_NONE);
  ast_node_set_position(holder, parser->current.line, parser->current.column);

  // NO_IDENT_OPERAND -> L_PAREN INLINE_VALUE R_PAREN, the value is an if
  parser_advance(ctx, parser);
  parse_if_inline(ctx, parser, holder);
  parser_expect(ctx, parser, R_PAREN);

  AstNode* if_node;
  ast_node_detach_child(ctx, holder, 0, &if_node);
  stack->data[index].node = if_node;
  ast_node_destroy(ctx, holder);
}

